const list=route==='tasks'?tasks:route==='orders'?orders:route==='agents'?agents:deals;const setList=route==='tasks'?setTasks:route==='orders'?setOrders:route==='agents'?setAgents:setDeals;const filtered=list.filter(d=>(d.name+' '+d.channel+' '+d.owner).toLowerCase().includes(search.toLowerCase())&&(filter==='Все'||d.channel===filter||d.status===filter));
function create(form:HTMLFormElement){const f=new FormData(form);const name=String(f.get('name')||'').trim();if(!name){notify('Укажите имя или название');return}const clientRecord=['crm','customers','conversations'].includes(route);const item:Entity={...detail,...(clientRecord?{pipeline:String(f.get('pipeline')||(detail?dealPipeline(detail):createPipeline)) as Pipeline,phone:String(f.get('phone')||'').trim(),city:String(f.get('city')||'')}:{}),id:detail?.id||crypto.randomUUID(),name,createdAt:detail?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),value:Number(f.get('value')||0),status:String(f.get('status')||'Активен'),channel:String(f.get('channel')||'WhatsApp'),owner:String(f.get('owner')||''),note:String(f.get('note')||'')};setList(l=>detail?l.map(x=>x.id===detail.id?item:x):[item,...l]);if(route==='conversations')setSelectedChatId(item.id);audit((detail?'Изменено: ':'Создано: ')+item.name);setDetail(null);setModal('');notify('Изменения сохранены')}
async function setup(){if(!setupText.trim())return;setSetupReady(false);for(let i=0;i<12;i++){setSetupStep(i);await new Promise(r=>setTimeout(r,190))}setSetupStep(-1);setSetupReady(true)}
const setupItems=['CRM: воронка и 10 этапов','14 пользовательских полей','3 роли сотрудников','4 AI-агента','8 автоматизаций','Товароучёт и основной склад','3 дашборда','6 аналитических виджетов'];const [approved,setApproved]=useState(setupItems.map(()=>true));
