if(runtimeError)return <ErrorScreen code={runtimeError} retry={()=>{setRuntimeError(null);go('dashboard')}}/>;if(route==='errors'){const code=Number(initialPath.split('/')[2])||404;return <ErrorScreen code={code} preview={initialPath.startsWith('/errors/')} retry={()=>go('dashboard')}/>;}
